#!/usr/bin/env node

/**
 * Convert the `map` files into json
 * 
 * All maps begin with the lines:
 * 
 *     type octile
 *     height x
 *     width y
 *     map
 * 
 * where x and y are the repsective height and width of the map.
 * 
 * The map data is store as an ASCII grid. The following characters are possible:
 * 
 *     . - passable terrain
 *     G - passable terrain
 *     @ - out of bounds
 *     O - out of bounds
 *     T - trees (unpassable)
 *     S - swamp (passable from regular terrain)
 *     W - water (traversable, but not passable from terrain)
 * 
 */

/**
 * Implementation note:
 * For convenience, only '.' and 'G' are interpreted as walkable.
 */

var fs = require('fs');
var endOfLine = require('os').EOL;

function parse(filename) {
  var content = fs.readFileSync(filename).toString();
  var lines = content.split(endOfLine);
  return {
    height : parseInt(lines[1].split(' ')[1]),
    width  : parseInt(lines[2].split(' ')[1]),
    grid   : parseGrid(lines.slice(4)),
  };
}
exports.parse = parse;

function parseGrid(lines) {
  var grid = [];
  lines.forEach(function(line) {
    if (!line.length) {
      return;
    }
    var row = [];
    line.split('').forEach(function(char) {
      row.push(char in { '.': 1, 'G': 1 } ? 0 : 1);
    });
    grid.push(row);
  });
  return grid;
}

function splitext(filename) {
  var index = filename.lastIndexOf('.');
  if (index < 0) {
    return [filename, ''];
  } else {
    return [filename.substr(0, index), filename.substr(index)];
  }
}

function main(argv) {
  var filename = argv[2];
  var obj = parse(filename);
  var root = splitext(filename)[0];
  fs.writeFileSync(root + '.json', JSON.stringify(obj));
}

if (!module.parent) {
  main(process.argv);
}
#!/usr/bin/env node

/**
 * The scenario files have the following format.
 * The begin with the text "version x.x". This document describes version 1.0. 
 * The trailing 0 is optional.
 *
 * Each line of a scenario has 9 fields:
 *
 * Bucket
 * map 
 * map width
 * map height 
 * start x-coordinate
 * start y-coordinate
 * goal x-coordinate
 * goal y-coordinate
 * optimal length
 */

var fs = require('fs');

function parse(filename) {
  var content = fs.readFileSync(filename).toString();
  var lines = content.split('\n');
  var version = lines[1].split(/\s+/);
  return {
    version: version,
    scenarios: lines.slice(1, lines.length - 1).map(parseLine)
  };
}

function parseLine(line) {
  var fields = line.split(/\s+/);
  return {
    bucket: parseInt(fields[0]),
    map: fields[1],
    width: parseInt(fields[2]),
    height: parseInt(fields[3]),
    startX: parseInt(fields[4]),
    startY: parseInt(fields[5]),
    endX: parseInt(fields[6]),
    endY: parseInt(fields[7]),
    length: parseFloat(fields[8])
  };
}

exports.parse = parse;
/**
 * the `select` field indicates which scenarios in the `scen` file are chosen 
 * to be included in the benchmark.
 */
module.exports = [
  {
    map: './map/64room_000.map',
    scen: './scen/64room_000.map.scen',
    select: [ 245, 1996 ]
  },
]

